using namespace std;
namespace {
QJsonArray checks,observed;QString scenario;
void Check(bool passed,const QString&name,bool precondition=false){checks.append(QJsonObject{{"case",scenario},{"name",name},{"passed",passed},{"precondition",precondition}});if(!passed)cerr<<"FAIL "<<scenario.toStdString()<<": "<<name.toStdString()<<'\n';if(precondition&&!passed)throw runtime_error(name.toStdString());}
QByteArray Read(const QString&path){QFile f(path);if(!f.open(QIODevice::ReadOnly))throw runtime_error(("read "+path).toStdString());return f.readAll();}
void Write(const QString&path,const QByteArray&data){if(!QDir().mkpath(QFileInfo(path).absolutePath()))throw runtime_error("mkdir");QFile f(path);if(!f.open(QIODevice::WriteOnly)||f.write(data)!=data.size())throw runtime_error(("write "+path).toStdString());}
QString Hash(const QByteArray&data){return QString::fromLatin1(QCryptographicHash::hash(data,QCryptographicHash::Sha256).toHex());}
QJsonObject Tree(const QString&path){QJsonObject result;QDirIterator it(path,QDir::Files|QDir::NoSymLinks,QDirIterator::Subdirectories);while(it.hasNext()){const auto f=it.next();result.insert(QDir(path).relativeFilePath(f),Hash(Read(f)));}return result;}
QString Native(const filesystem::path&path){return QString::fromStdString(path.u8string());}
QByteArray Locations(const QString&base){return "[General]\nMarker=imported\n[Locations]\nConfiguration="+(base+"/configuration").toUtf8()+"\nSceneCollections="+(base+"/scenes").toUtf8()+"\nProfiles="+(base+"/profiles").toUtf8()+"\nPluginManagerSettings="+(base+"/plugins").toUtf8()+"\n";}
CloudBackupRoots Setup(const QString&base){auto*a=App();auto path=filesystem::u8path(base.toStdString());a->userConfigLocation=path/"configuration";a->userScenesLocation=path/"scenes";a->userProfilesLocation=path/"profiles";a->userPluginManagerSettingsLocation=path/"plugins";globalConfigBase=path/"global";Write(base+"/configuration/obs-studio/user.ini","[General]\nMarker=local-user\n");Write(base+"/global/obs-studio/global.ini",QByteArray(Locations(base)).replace("Marker=imported","Marker=local"));for(const auto&dir:{base+"/scenes/obs-studio/basic/scenes",base+"/profiles/obs-studio/basic/profiles",base+"/plugins/obs-studio/plugin_manager",base+"/configuration/obs-studio/plugin_config"})Check(QDir().mkpath(dir),"prepare direct temporary root",true);CloudBackupRoots roots;QString error;Check(CloudBackupArchive::CaptureRoots(roots,error),"capture real immutable roots",true);return roots;}
QByteArray Archive(const QString&path,const QByteArray&data){QJsonArray files{QJsonObject{{"path",path},{"data",QString::fromLatin1(data.toBase64())},{"size",double(data.size())},{"sha256",Hash(data)}}};QJsonObject manifest{{"formatVersion",2},{"obsVersion","fixture"},{"computerName","fixture"},{"createdUtc","2026-10-23T00:00:00Z"},{"files",files},{"unpackedBytes",double(data.size())}};QByteArray result("OBSCLOUD2");result.append(char(0));result.append(qCompress(QJsonDocument(manifest).toJson(QJsonDocument::Compact)));return result;}
CloudBackupOptions Options(bool general){CloudBackupOptions result;result.generalSettings=general;result.scenes=!general;result.profiles=false;result.pluginSettings=false;result.preserveLocalDevices=false;return result;}
QString Marker(const CloudBackupRoots&r){return r.pendingRoot+"/pending.json";}
QString Stage(const CloudBackupRoots&r){return r.pendingRoot+"/stages/"+QJsonDocument::fromJson(Read(Marker(r))).object()["stageId"].toString();}
void MissingGlobal(const QString&base){scenario="missing-global-preserves-previous-intent";Setup(base+"/B");const auto r=Setup(base+"/A");Write(r.scenesRoot+"/collection.json","{\"graph\":\"local-scene-sentinel\"}");QString safety,error;Check(CloudBackupArchive::StageRestore(r,Archive("scenes/collection.json","{\"graph\":\"previous-pending\"}"),Options(false),safety,error),"seed real previous pending",true);const auto marker=Read(Marker(r));const auto oldStage=Stage(r);const auto stageTree=Tree(oldStage);const auto localGraph=Tree(r.scenesRoot);const auto user=Read(r.configRoot+"/user.ini");Check(QFile::remove(r.globalConfigPath),"local global missing before import",true);const bool result=CloudBackupArchive::StageRestore(r,Archive("general/global.ini",Locations(base+"/B")),Options(true),safety,error);Check(!result,"missing local global refuses imported global");Check(!error.isEmpty()&&error.contains("global.ini"),"failure explains the local global problem");Check(Read(Marker(r))==marker&&Tree(oldStage)==stageTree,"previous pointer and complete stage preserved");Check(Tree(r.scenesRoot)==localGraph&&Read(r.configRoot+"/user.ini")==user,"local scene graph and user configuration unchanged");Check(!QFileInfo::exists(r.globalConfigPath),"rejected staging does not synthesize local global");observed.append(QJsonObject{{"case",scenario},{"stage_return",result},{"error",error},{"previous_marker_sha256",Hash(marker)},{"final_marker_sha256",Hash(Read(Marker(r)))}});}
void ReadableGlobal(const QString&base){scenario="readable-local-locations-control";Setup(base+"/B");const auto r=Setup(base+"/A");QString safety,error;Check(CloudBackupArchive::StageRestore(r,Archive("general/global.ini",Locations(base+"/B")),Options(true),safety,error),"readable local global accepts Stage",true);const auto staged=Read(Stage(r)+"/files/general/global.ini");Check(staged.contains((base+"/A/configuration").toUtf8())&&!staged.contains((base+"/B").toUtf8()),"staged global preserves custom local Locations A");Check(CloudBackupArchive::ApplyPendingRestore(r,error),"real same-root Apply succeeds",true);QSettings global(r.globalConfigPath,QSettings::IniFormat);Check(global.value("Locations/Configuration").toString()==base+"/A/configuration"&&global.value("Locations/SceneCollections").toString()==base+"/A/scenes","independent INI read retains existing custom configuration and scene locations");Check(Read(r.globalConfigPath).contains("Marker=imported")&&!Read(r.globalConfigPath).contains("Marker=local"),"unrelated incoming General content restored");Check(!CloudBackupArchive::HasPendingRestore(r),"successful Apply retires pointer");observed.append(QJsonObject{{"case",scenario},{"stage_preserved_A",!staged.contains((base+"/B").toUtf8())},{"applied_global_sha256",Hash(Read(r.globalConfigPath))}});}
void NoGlobalTransport(const QString&base){scenario="no-global-transport-missing-local-control";Setup(base+"/B");const auto r=Setup(base+"/A");Write(r.scenesRoot+"/collection.json","{\"graph\":\"preserve\"}");const auto graph=Tree(r.scenesRoot);Check(QFile::remove(r.globalConfigPath),"remove only synthetic global",true);QString safety,error;const auto user=Locations(base+"/B");Check(CloudBackupArchive::StageRestore(r,Archive("general/user.ini",user),Options(true),safety,error),"transport without global still stages with missing local global",true);Check(CloudBackupArchive::ApplyPendingRestore(r,error),"user-only real Apply succeeds",true);Check(Read(r.configRoot+"/user.ini")==user,"user.ini Locations remain ordinary restored content");Check(!QFileInfo::exists(r.globalConfigPath)&&Tree(r.scenesRoot)==graph,"no global invented and local graph preserved");Check(!CloudBackupArchive::HasPendingRestore(r),"user-only pointer retired");observed.append(QJsonObject{{"case",scenario},{"global_still_absent",!QFileInfo::exists(r.globalConfigPath)}});}
}
int main(int argc,char**argv){const auto root=QDir::fromNativeSeparators(qEnvironmentVariable("STUDIO_ARCHIVE_TEST_ROOT"));if(root.isEmpty()||!QDir::isAbsolutePath(root)||QFileInfo::exists(root+"/cases")){cerr<<"Set STUDIO_ARCHIVE_TEST_ROOT to a new absolute fixture directory.\n";return 2;}
#ifdef _WIN32
 if(qEnvironmentVariable("STUDIO_ARCHIVE_PRIVATE_WINDOWS")!="1"){cerr<<"Windows requires an isolated QA account/VM and STUDIO_ARCHIVE_PRIVATE_WINDOWS=1.\n";return 2;}QStandardPaths::setTestModeEnabled(true);
#endif
 qputenv("XDG_CACHE_HOME",(root+"/cache").toUtf8());qputenv("XDG_CONFIG_HOME",(root+"/xdg-config").toUtf8());qputenv("XDG_DATA_HOME",(root+"/xdg-data").toUtf8());QCoreApplication app(argc,argv);const QList<QPair<QString,void(*)(const QString&)>> cases{{"missing",MissingGlobal},{"readable",ReadableGlobal},{"without-global",NoGlobalTransport}};for(const auto&c:cases){try{c.second(root+"/cases/"+c.first);}catch(const exception&e){Check(false,QString::fromUtf8(e.what()));}}
 Check(credentialCalls==0&&credentialMetadataCalls==0,"zero credential operations or metadata reads");int failures=0,preconditions=0;for(const auto&entry:checks){const auto c=entry.toObject();if(!c["passed"].toBool()){++failures;if(c["precondition"].toBool())++preconditions;}}QJsonObject report{{"checks",checks},{"failures",failures},{"precondition_failures",preconditions},{"credential_calls",credentialCalls},{"credential_metadata_calls",credentialMetadataCalls},{"observed",observed},{"scope","Real Archive/CreateSnapshot/Stage/Apply and serializer/Crypto; temporary App paths, denied counted credential dependencies. INI value read is not a full application startup or GUI test."}};Write(root+"/result.json",QJsonDocument(report).toJson(QJsonDocument::Indented));cout<<"{\"checks\":"<<checks.size()<<",\"failures\":"<<failures<<",\"precondition_failures\":"<<preconditions<<"}\n";return failures?1:0;}
